function initial(){return {v:1,app:'home',view:'',time:21*60+17,elapsed:0,applied:false,hired:false,arrived:false,checked:false,uploads:[],photos:[],marks:{},flags:{},messages:{mom:[{text:'小砚，今天投了几家？',at:'21:12'},{text:'毕业都三个月了。你表弟下周都去报到了。',at:'21:14'},{text:'先找个工作做起来，别总一个人闷在出租屋。',at:'21:17'}],dad:[{text:'先就业，再择业。找工作别怕吃苦。',at:'20:56'},{text:'你妈就是嘴急，真缺钱了跟爸说。',at:'21:03'}],friend:[{text:'面试怎么样？',at:'19:42'},{text:'别忘了咱俩说好的，拿第一份工资去吃火锅。',at:'19:44'}],landlord:[{text:'小林，周五该交房租了，记得哦。',at:'18:28'}],class:[{text:'班长：还没填就业去向的同学，今晚之前记得填表。',at:'20:31'}]},unread:{mom:3},notes:'房租：周五。\n简历改完记得发给小张是好bro看。\n\n第一份工资，请大家吃火锅。',settings:{sound:true,intense:true},route:null,ending:null,query:'',history:[],read:[],drafts:{},calls:[],flash:true,report:{name:'',finding:'unknown'}};}
function readSave(){try{const v=GameStorage.read();if(v?.v===1)return {...initial(),...v,settings:{...initial().settings,...v.settings},flags:v.flags||{},drafts:v.drafts||{}};}catch{}return initial();}
let S=readSave();let R={zoom:false,compare:false,marking:false,notice:null,noticeLeft:0,scareLeft:0,scareText:'',busy:false,muted:false};let imageCache={},audioCtx=null,ambience=null,lastFrame=performance.now(),lastSaved=0;
function save(){return GameStorage.write(S);}
function checkpoint(){try{localStorage.setItem(CHECKPOINT,JSON.stringify({...S,ending:null,app:'stay',view:''}));}catch{}}
function time(){const m=Math.floor(S.time)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
function nowAdd(min){S.time+=min;save();}
function hasPhoto(id){return S.photos.some(p=>p.room===id);}
function unlocked(id){return S.checked&&(ROOMS.findIndex(r=>r.id===id)<=S.uploads.length);}
function nextRoom(){return ROOMS[Math.min(S.uploads.length,ROOMS.length-1)].id;}
function addMsg(id,text,self=false,extra={}){S.messages[id]??=[];S.messages[id].push({text,self,at:time(),...extra});if(!self&&!extra.system&&!(S.app==='wechat'&&S.view===id))S.unread[id]=(S.unread[id]||0)+1;save();}
function notify(title,text,app='wechat',view=''){R.notice={title,text,app,view};R.noticeLeft=5300;renderNotice();tone('notify');}
function renderNotice(){const e=$('#notification');e.classList.toggle('visible',R.noticeLeft>0);e.innerHTML=R.notice?B('notice',`<small>${esc(R.notice.title)}<span style="float:right">${time()}</span></small><b>${esc(R.notice.text)}</b>`,'notice'):'';}
function sheet(title,content){$('#modal').innerHTML=`<section class="sheet"><div class="sheet-head"><h2>${esc(title)}</h2>${B('close','×')}</div>${content}</section>`;}
function close(){ $('#modal').innerHTML=''; }
function open(app,view=''){if(!APP_NAMES[app])return;S.app=app;S.view=view;R.zoom=R.compare=R.marking=false;close();R.noticeLeft=0;renderNotice();if(app==='wechat'&&PEOPLE[view])S.unread[view]=0;save();render();}
function appHeader(title,backAction='back',right=''){return `<div class="topbar">${B(backAction,I('back'),'',{label:'返回'})}<h1>${esc(title)}</h1>${right||'<span style="width:40px"></span>'}</div>`;}
function primary(action,text,data={}){return B(action,esc(text),'primary',data);}
function tabs(items,selected){return `<div class="tabs">${items.map(([id,label,icon])=>B('tab',`<span class="wx-tab-icon">${I(icon)}${id==='chats'?wxUnreadBadge(wxUnreadTotal()):''}</span><span>${label}</span>`,id===selected?'selected':'',{id})).join('')}</div>`;}
function tone(type){if(!S.settings.sound||R.muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume().catch(()=>{});if(type==='tap')return;const t=audioCtx.currentTime;const out=audioCtx.createGain();out.gain.value=type==='scare'?.16:.045;out.connect(audioCtx.destination);const osc=audioCtx.createOscillator();osc.type=type==='scare'?'sawtooth':'sine';osc.frequency.setValueAtTime(type==='scare'?150:type==='shutter'?680:880,t);osc.frequency.exponentialRampToValueAtTime(type==='scare'?39:type==='shutter'?100:620,t+.22);const env=audioCtx.createGain();env.gain.setValueAtTime(.01,t);env.gain.linearRampToValueAtTime(1,t+.015);env.gain.exponentialRampToValueAtTime(.001,t+(type==='scare'?.8:.24));osc.connect(env);env.connect(out);osc.start();osc.stop(t+1);if(type==='knock'){setTimeout(()=>tone('shutter'),260);setTimeout(()=>tone('shutter'),580);}}catch{}}
function syncAmbience(){if(!audioCtx)return;if(ambience){ambience.gain.gain.value=S.settings.sound&&S.checked&&!S.ending&&!document.hidden?.014:0;return;}try{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=49;gain.gain.value=0;osc.connect(gain);gain.connect(audioCtx.destination);osc.start();ambience={osc,gain};syncAmbience();}catch{}}
function scare(text){if(R.scareLeft)return;R.scareLeft=S.settings.intense?1250:1550;R.scareText=text;const el=$('#scare');el.className='visible'+(S.settings.intense?'':' soft');el.innerHTML=`<img src="assets/scare.png" alt="突然贴近镜头的女人"><p>${esc(text)}</p>`;el.setAttribute('aria-hidden','false');tone(S.settings.intense?'scare':'notify');}
function renderStatus(){const battery=Math.max(12,87-S.photos.length*5-Math.floor(S.elapsed/180000));$('#status').innerHTML=`<span>${time()}</span><div class="island"></div><div class="vitals">${I('signal')}${I('wifi')}<span>4G</span><span class="battery"><b>${battery}</b></span></div>`;}
function appIcon(id,dock=false){const unread=id==='wechat'?wxUnreadTotal():id==='stay'&&S.hired&&!S.ending?1:0;return B('open',`<span class="appicon ${id}">${id==='biss'?'biss':I(id==='stay'?'home':id)}${unread?`<b class="badge" aria-label="${unread}条未读消息">${unread>99?'99+':unread}</b>`:''}</span><span>${APP_NAMES[id]}</span>`,'app',{app:id});}
function home(){return `<div class="home"><div class="widgets">${B('weather','<span>临川</span><strong>18°</strong><small>小雨 · 体感 16°</small><small>最高 20°　最低 16°</small>','widget weather')}${B('calendar','<small>星期日</small><strong>13</strong><span>今天没有日程</span>','widget calendar')}</div><div class="apps">${['wechat','biss','stay','camera','photos','browser','map','settings','notes','clock','files','phone'].map(id=>appIcon(id)).join('')}</div><div class="home-spacer"></div>${B('open','⌕ 搜索','home-search',{app:'browser'})}<div class="dock">${['phone','wechat','browser','camera'].map(id=>appIcon(id,true)).join('')}</div></div>`;}
const CHAT_TABS=[['chats','威信','wechat'],['contacts','通讯录','user'],['discover','发现','browser'],['me','我','user']];
function wechat(){const v=S.view||'chats';if(PEOPLE[v])return chat(v);if(v.startsWith('profile:'))return profile(v.slice(8));if(v==='moments')return moments();if(v==='contacts')return appHeader('通讯录','home',B('contacts-help',I('plus')))+`<div class="scroll chats">${Object.keys(PEOPLE).filter(id=>S.messages[id]).map(id=>B('profile',`${AV(id)}<div class="rowtext"><b>${PEOPLE[id].name}</b><p>${PEOPLE[id].note}</p></div>`,'chatrow',{id})).join('')}</div>`+tabs(CHAT_TABS,v);if(v==='discover')return appHeader('发现','home')+`<div class="scroll">${B('moments',I('camera')+'<span>朋友圈</span>'+I('next'),'setting')}${B('open',I('search')+'<span>搜一搜</span>'+I('next'),'setting',{app:'browser'})}</div>`+tabs(CHAT_TABS,v);if(v==='me')return appHeader('我','home')+`<div class="scroll"><div class="contactcard"><img class="avatar" src="assets/player-avatar.png" alt="林砚"><h2>林砚</h2><p>威信号：yan_after_graduation</p><p>个性签名：要有新的开始。</p></div>${B('moments','我的朋友圈'+I('next'),'setting')}${B('open','收藏的照片'+I('next'),'setting',{app:'photos'})}${B('open','设置'+I('next'),'setting',{app:'settings'})}</div>`+tabs(CHAT_TABS,v);
return appHeader('威信','home',B('wx-search',I('search')))+`<div class="scroll chats">${Object.keys(S.messages).reverse().sort((a,b)=>Number(S.unread[b]>0)-Number(S.unread[a]>0)).map(id=>{const msgs=S.messages[id],m=msgs.at(-1);return B('chat',`${AV(id)}<div class="rowtext"><time>${m?.at||''}</time><b>${esc(PEOPLE[id].name)}${S.unread[id]?` <small style="color:#e85d59">${S.unread[id]}</small>`:''}</b><p>${esc(m?.image?'[图片]':m?.text||'')}</p></div>`,'chatrow',{id});}).join('')}</div>`+tabs(CHAT_TABS,'chats');}
function chat(id){const p=PEOPLE[id],msgs=S.messages[id]||[];let choices=[];if(id==='mom'&&!S.flags.repliedMom)choices=[['reply','还在投，别担心。',{id,text:'还在投，别担心。'}],['reply','我再看看招聘。',{id,text:'我再看看招聘。'}]];else if(id==='mom'&&S.photos.length>=4&&!S.flags.calledMom)choices=[['call','给妈妈打电话',{id:'mom'}]];else if(id==='hr'&&!S.hired)choices=[['accept-offer','接受试岗，查看地址',{}],['ask-risk','这房子真的出过事？',{}]];else if(id==='hr'&&S.hired&&!S.checked)choices=[['open','查看试睡订单',{app:'stay'}]];else if(id==='hr'&&S.checked)choices=[['open','打开工作清单',{app:'stay'}],['hr-question','照片里有人',{}]];else if(id==='friend'&&S.photos.length>=2)choices=[['share-friend','把异常照片发给小张是好bro',{}],['call','打电话',{id:'friend'}]];else if(id==='unknown')choices=[['ask-unknown','你是上一位试睡员？',{}],['open','去浏览器搜“住过604的人”',{app:'browser'}]];
return appHeader(p.name,'wx-list',B('call',I('phone'),'',{id}))+`<div class="scroll chatbody" id="chatbody"><div class="chat-time">9月13日　${msgs[0]?.at||time()}</div>${msgs.map(m=>`<div class="msg ${m.self?'self':''}">${m.self?'<img class="avatar" src="assets/player-avatar.png" alt="我">':AV(id)}${m.image?B('view-photo',`<img src="assets/${room(m.image).photo}" alt="${room(m.image).name}照片">`,'bubble photo',{id:m.image}):`<div class="bubble">${esc(m.text)}</div>`}</div>`).join('')}</div>${choices.length?`<div class="chat-choices">${choices.map(([a,l,d])=>B(a,esc(l),'',d)).join('')}</div>`:''}<form class="composer" id="chat-form" data-id="${id}">${B('call',I('sound'),'',{id})}<input id="chat-input" aria-label="消息" autocomplete="off" maxlength="300" value="${esc(S.drafts[id]||'')}">${B('attach',I('plus'),'',{id})}<button class="send" type="submit">发送</button></form>`;}
function profile(id){const p=PEOPLE[id];return appHeader('详细资料','wx-list')+`<div class="scroll"><div class="contactcard">${AV(id)}<h2>${p.name}</h2><p>${p.note} · 临川</p></div><div class="pad stack">${primary('chat','发消息',{id})}${B('call','语音通话','secondary',{id})}${B('moments','朋友圈','secondary')}</div></div>`;}
function moments(){return appHeader('朋友圈','wx-discover')+`<div class="scroll"><img src="assets/wx-cover-self-v6.png" style="width:100%;height:165px;object-fit:cover" alt="生活封面"><div class="moment">${AV('friend')}<div class="content"><b>小张是好bro</b><p>入职第一天。工牌拍了八遍，还是像没睡醒。</p><small>今天 18:30　${B('like',S.flags.liked?'♥ 你已赞':'♡ 赞','',{id:'friend'})}</small></div></div><div class="moment">${AV('mom')}<div class="content"><b>妈妈</b><p>等小砚回来，包她爱吃的荠菜馄饨。</p><small>昨天 17:26</small></div></div><div class="moment">${AV('dad')}<div class="content"><b>爸爸</b><p>天晴了。年轻人慢慢来，路还长。</p><img class="cover" src="assets/wx-mountain.png" alt="山间风景"><small>昨天 09:21</small></div></div>${S.photos.length>=3?`<div class="moment">${AV('unknown')}<div class="content"><b>住过604的人</b><p>有人问我，试睡的时候最怕什么。<br>不是睁着眼看到她。<br>是闭上眼之后，她还在照片里看你。</p><small>刚刚</small></div></div>`:''}</div>`;}
const JOBS=[{id:'normal1',name:'新媒体运营助理',pay:'4—6K',tags:['临川 · 江北区','经验不限','本科'],company:'知序文化 · 20—99人',hr:'许女士 · 人事',desc:'协助整理选题、文案及活动资料。需提供作品集，每周五天工作制。'},{id:'haunted',name:'凶宅试睡员 · 夜间体验',pay:'1200元/晚',tags:['日结','接受应届生','无需经验'],company:'安住不动产 · 房源体验',hr:'周先生 · 负责人',desc:'对有特殊历史的待售房源进行夜间居住体验，拍摄房间细节，提交真实体验报告。'},{id:'normal2',name:'行政前台',pay:'3—4K',tags:['临川 · 城南','1—3年','大专'],company:'禾木商务 · 100—499人',hr:'王女士 · HR',desc:'负责前台接待、电话转接及会议室管理。需有相关工作经验。'}];
function biss(){if(S.view==='resume')return appHeader('我的简历','biss-home')+`<div class="scroll pad"><div class="card"><h2>林砚</h2><p>22岁 · 本科 · 应届毕业生</p><p>临川学院 · 新闻传播专业</p><div class="tags"><span>摄影</span><span>内容编辑</span><span>可立即到岗</span></div><p>求职状态：${S.hired?'已有试岗安排':'离校未就业'}</p></div><div class="card"><h3>沟通记录</h3><p>${S.applied?'安住不动产：已沟通，今晚试岗。':'投递 27 家 · 3 家已读 · 暂无面试邀请'}</p></div></div>`;
if(S.view==='messages')return appHeader('沟通','biss-home')+`<div class="scroll pad">${S.applied?B('chat',`${AV('hr')}<div class="rowtext"><b>周先生 · 安住不动产</b><p>后续通过威信联系，点击继续沟通。</p></div>`,'chatrow',{id:'hr'}):'<p class="empty">尚无新的沟通消息。</p>'}</div>`;
if(S.view.startsWith('job:')){const j=JOBS.find(x=>x.id===S.view.slice(4))||JOBS[1],h=j.id==='haunted';return appHeader('职位详情','biss-home',B('save-job',I('heart')))+`<div class="scroll jobdesc"><div class="eyebrow">${h?'安住不动产 · 房源体验':'全职岗位'}</div><h2>${j.name}</h2><strong style="color:#04a69e;font-size:24px">${j.pay}</strong><div class="tags">${j.tags.map(t=>`<span>${t}</span>`).join('')}</div><h3>职位描述</h3><p>${j.desc}</p>${h?'<ul><li>23:50 前到达，独立入住至次日清晨。</li><li>拍摄玄关、客厅、浴室、卧室及入户门。</li><li>工作期间保持手机畅通，按负责人要求补拍。</li><li>无需直播，不接触客户，不收取押金。</li></ul><h3>关于特殊房源</h3><p>房屋曾发生非正常死亡事件。请自行评估是否适合夜间独处。报酬于提交完整报告后结算。</p><h3>房源位置</h3><p>临川 · 槐安里小区<br>具体门牌在确认试岗后提供。</p>':'<h3>任职要求</h3><p>'+j.desc+'</p>'}<h3>招聘人</h3><p>${j.hr} · 刚刚活跃</p></div><div class="sticky-actions">${primary(h?'apply':'normal-apply',S.applied&&h?'继续沟通':'立即沟通',{id:j.id})}</div>`;}
return `<div class="biss-head"><b>biss直聘</b><span>临川⌄</span></div><div style="padding:0 18px 13px;background:#d8f7f0">${B('job-search',I('search')+'<span>搜索职位 / 公司</span>','searchbox',{label:'搜索职位'})}</div><div class="biss-filter"><b>推荐</b><span>附近</span><span>应届生</span><span>不限经验</span></div><div class="scroll">${JOBS.map(j=>B('job',`<span class="salary">${j.pay}</span><h2>${j.name}</h2><div class="tags">${j.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="company">${j.company}</div><div class="recruiter"><span class="avatar brand">${j.hr[0]}</span>${j.hr}<span style="margin-left:auto;color:#16a895">刚刚活跃</span></div>`,'job',{id:j.id})).join('')}</div>`+tabs([['jobs','职位','files'],['biss-messages','消息','wechat'],['resume','我的','user']],'jobs');}
function stay(){if(S.view==='report')return report();if(!S.hired)return appHeader('安住试睡','home')+`<div class="scroll"><div class="stayhero"><small>ANZHU · PROPERTY EXPERIENCE</small><h2>每间房，都有一个故事。</h2><p>房源夜间体验 · 真实记录 · 按晚结算</p></div><div class="pad"><div class="card"><h3>暂无进行中的试睡订单</h3><p>接受招聘人的试岗邀请后，订单会显示在这里。</p>${primary('open','前往 biss直聘',{app:'biss'})}</div></div></div>`;
return appHeader('我的试睡','home',B('chat',I('wechat'),'',{id:'hr'}))+`<div class="scroll"><div class="stayhero"><small>ANZHU · NIGHT STAY　/　NO. 0913</small><h2>槐安里 · 6栋604</h2><span class="amount">¥${S.uploads.length>=4?'1800':'1200'}</span><p>今晚 23:50 — 次日 06:00<br>${S.checked?'试睡中 · 独立体验':'待报到 · 林砚'}</p></div><div class="pad">${!S.arrived?`<div class="card"><h3>前往房源</h3><p>钥匙在门口密码盒。到达后联系负责人取钥匙。</p>${primary('open','查看地图',{app:'map'})}</div>`:!S.checked?`<div class="card"><h3>你已到达 6栋楼下</h3><p>周先生：上六楼，604。钥匙盒密码 0614。开门后先拍玄关，不要挪屋里的东西。</p>${primary('checkin','取钥匙，进入604')}</div>`:''}<div class="card"><div class="eyebrow">房源影像记录</div><h3>${S.uploads.length}/5 张已提交</h3><div class="progressline"><i style="width:${S.uploads.length*20}%"></i></div>${ROOMS.map((r,i)=>B('task',`<span class="tasknum">${S.uploads.includes(r.id)?I('check'):String(i+1).padStart(2,'0')}</span><span class="tasktext"><b>${r.name}</b><small>${S.uploads.includes(r.id)?'已提交 · 可查看原片':hasPhoto(r.id)?'已拍摄 · 待提交':unlocked(r.id)?r.subtitle:'等待前一项完成'}</small></span>${I(unlocked(r.id)?'next':'lock')}`,'taskrow '+(S.uploads.includes(r.id)?'done':''),{id:r.id})).join('')}</div>${S.uploads.length===5?`<div class="card"><h3>夜间体验报告</h3><p>请据实填写房屋居住情况。最终签名将归入本次房源档案。</p>${primary('report','填写体验报告')}</div>`:''}${S.checked?B('leave-early','终止试睡 / 联系负责人','secondary'):''}<p class="muted" style="text-align:center;margin-top:18px">安住不动产 · 夜间房源体验</p></div></div>`;}
function camera(){if(!S.checked)return appHeader('相机','home')+`<div class="empty">当前位于出租屋。<br>到达试睡房源后，可以按工作清单拍摄。${B('open','查看订单','primary',{app:'stay'})}</div>`;let r=room(S.view||nextRoom());if(!unlocked(r.id))r=room(nextRoom());return `<div class="camera-top">${B('open',I('back'),'',{app:'stay'})}${B('flash',I('flash')+(S.flash?'自动':'关闭'))}<span>RAW　2:3</span>${B('camera-help',I('dots'))}</div><div class="viewfinder"><canvas id="camera-canvas" aria-label="${r.name}实时取景"></canvas><div class="focus"></div><div class="view-caption">${r.caption}</div></div><div class="room-selector">${ROOMS.filter(x=>unlocked(x.id)).map(x=>B('room',esc(x.name),x.id===r.id?'selected':'',{id:x.id})).join('')}</div><div class="camera-bottom"><div class="camera-modes"><span>视频</span><b>照片</b><span>人像</span></div><div class="shutterbar">${B('latest-photo',S.photos.length?`<img src="assets/${room(S.photos.at(-1).room).photo}" alt="最近照片">`:I('photos'),'thumb')}${B('shutter','','shutter',{id:r.id,label:'拍照'})}${B('camera-help',I('rotate'))}</div></div>`;}
function loadImage(src){if(!imageCache[src]){const img=new Image();img.src='assets/'+src;imageCache[src]=img;}return imageCache[src];}
function drawCamera(){const c=$('#camera-canvas');if(!c)return;const r=room(S.view||nextRoom()),img=loadImage(r.live);const draw=()=>{if(!c.isConnected)return;const rect=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr);const ctx=c.getContext('2d');ctx.fillStyle='#080c0a';ctx.fillRect(0,0,c.width,c.height);const scale=Math.min(c.width/img.naturalWidth,c.height/img.naturalHeight);const w=img.naturalWidth*scale,h=img.naturalHeight*scale;ctx.drawImage(img,(c.width-w)/2,(c.height-h)/2,w,h);};if(img.complete&&img.naturalWidth)draw();else img.onload=draw;}
function photos(){return appHeader('照片','home')+`<div class="scroll"><div class="pad"><h2 style="font-size:29px">最近项目</h2><p class="muted">${S.photos.length} 张照片 · 保存在本机</p></div>${S.photos.length?`<div class="album">${S.photos.map(p=>B('view-photo',`<img src="assets/${room(p.room).photo}" alt="${room(p.room).name}"><small>${room(p.room).name}${S.marks[p.room]?' ◉':''}</small>`,'',{id:p.room})).join('')}</div>`:'<p class="empty">还没有拍摄照片。</p>'}</div>`;}
function photo(){const r=room(S.view),p=S.photos.find(p=>p.room===r.id);if(!p)return appHeader('照片','home')+'<p class="empty">尚未拍摄该照片。</p>';return appHeader(r.name,'photo-back',B('photo-details',I('dots'),'',{id:r.id}))+`<div class="photo-stage ${R.zoom?'zoomed':''}" id="photo-stage"><img id="evidence-image" draggable="false" src="assets/${R.compare?r.live:r.photo}" alt="${r.name}${R.compare?'快门前取景':'拍摄原片'}" data-room="${r.id}"></div><div class="photo-info"><small>${R.compare?'快门前 · 取景缓存':'IMG_0913_'+String(ROOMS.indexOf(r)+1).padStart(2,'0')+' · '+p.at}　${R.marking?'点选照片中不对劲的位置':R.compare?'对照画面':S.marks[r.id]?'已标记异常':'原始照片'}</small><p>${R.compare?'这是按下快门前，屏幕里最后一帧画面。':S.marks[r.id]?r.clue:r.id==='hall'?'门关着。红鞋在左侧鞋柜上。':R.marking?'可先放大照片。标记会保留在体验报告里。':'可以放大查看，并与快门前的取景画面对照。'}</p></div><div class="photo-tools">${B('zoom',I('search')+(R.zoom?'缩小':'放大'),R.zoom?'selected':'')}${B('compare',I('compare')+(R.compare?'返回原片':'取景对照'),R.compare?'selected':'')}${B('mark',I('mark')+'标记异常',R.marking?'selected':'',{id:r.id})}${B('upload',I(S.uploads.includes(r.id)?'check':'upload')+(S.uploads.includes(r.id)?'查看清单':'发给雇主'),'',{id:r.id})}</div>`;}
function mapView(){return appHeader('地图','home')+`<div class="map-panel"><svg viewBox="0 0 380 470" preserveAspectRatio="xMidYMid slice" aria-label="前往槐安里小区的路线"><rect width="380" height="470" fill="#e9ecdf"/>${[[8,45,74,65],[100,45,90,65],[210,45,140,65],[0,133,80,84],[98,133,100,84],[220,135,155,75],[0,245,70,88],[90,242,105,90],[220,240,90,92],[320,240,65,92],[0,360,78,80],[100,360,93,110],[220,360,170,90]].map(([x,y,w,h],i)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${i===4?'#c7dbc1':'#d8dfd3'}"/>`).join('')}<path d="M-20 119H410 M-20 229H410 M-20 348H410 M89 0v490 M207 0v490" fill="none" stroke="#fff" stroke-width="15"/><path d="M39 347h169V169h42" stroke="#79a6d7" stroke-width="8" fill="none" stroke-linecap="round"/><path d="M39 347h169V169h42" stroke="#fff" stroke-width="2" stroke-dasharray="4 9" fill="none"/><circle cx="${S.arrived?250:39+(S.route?Math.min(S.route.elapsed/6500,1)*169:0)}" cy="${S.arrived?169:347}" r="9" fill="#3588ea" stroke="white" stroke-width="3"/><circle cx="250" cy="169" r="6" fill="#cb7562"/><text x="120" y="113" font-size="10" fill="#95a19b">槐安路</text><text x="245" y="344" font-size="10" fill="#95a19b">江北路</text><text x="112" y="175" font-size="10" fill="#83a778">街心花园</text><text x="20" y="390" font-size="10" fill="#9ba6a0">你租住的小区</text></svg><div class="mapsearch">⌕　槐安里小区 6栋</div><div class="maplabel">槐安里 · 6栋604</div></div><div class="mapcard"><div class="eyebrow">${S.arrived?'已到达目的地':'步行 + 公交'}</div><h2>${S.arrived?'槐安里小区':'前往试睡房源'}</h2><p>${S.arrived?'6栋 · 六楼 · 604室':S.hired?'2.4公里 · 预计32分钟 · 江北路方向':'接受试岗后可以开始导航'}</p>${S.route?`<div class="routeprogress"><i id="route-fill" style="width:${Math.min(S.route.elapsed/6500,1)*100}%"></i></div><p id="route-text">正在前往房源 · ${Math.floor(S.route.elapsed/6500*100)}%</p>${B('route-pause',S.route.paused?'继续导航':'暂停导航','secondary')}`:S.arrived?primary('open','查看入住指引',{app:'stay'}):S.hired?primary('navigate','开始导航'):primary('open','查看招聘',{app:'biss'})}</div>`;}
const ARTICLES=[
{id:'news',source:'临川晚报 · 旧闻',title:'槐安里旧楼租赁纠纷：被反复挂牌的604室',keys:['槐安里','604','凶宅','死亡','安住','屋主'],snippet:'邻居仍记得原住户沈秋宁。涉事房屋在她去世后，被以不同名义反复发布试住广告。',body:'<div class="masthead">临川晚报</div><h2>被反复挂牌的604室</h2><small class="muted">2021年6月18日 · 城市记录 / 后续回访</small><p>槐安里6栋604原住户<strong>沈秋宁</strong>，于2018年6月14日在家中死亡。社区工作人员表示，后续产权纠纷尚未解决，房屋长期空置。</p><p>一名老邻居说，她生前做裁缝，总穿一双红色绣花拖鞋。人去世后，鞋一直摆在玄关。报道配图中的绿皮沙发、婚纱照和老式衣柜，是她留下的家具。</p><p>近一年，居民多次发现有人深夜进入604，自称受雇来做“房源体验”。其中一位年轻人在<strong>夜住论坛</strong>发过长帖，账号名为<strong>住过604的人</strong>。</p><p>本报未能联系上广告中的负责人周某。社区提醒，该房屋仍有争议，挂牌广告并不等同于产权证明。</p><p class="muted">来源：社区回访及邻居采访。本文为游戏内虚构报道。</p>'},
{id:'forum',source:'夜住论坛 · 工作避坑',title:'我是“住过604的人”，别签那份独住报告',keys:['住过604的人','夜住论坛','试睡','604','安住','凶宅'],snippet:'他们说照片只是验收材料。但五个机位拍完，我发现每张照片里的她都离我更近。',body:'<div class="masthead" style="color:#40755e;border-color:#40755e">夜住论坛</div><h2>别签那份独住报告</h2><small class="muted">住过604的人 · 2024年9月17日</small><p>我也是从招聘软件来的。1200一晚，交五张照片，看见不干净的就说是反光。</p><p>第一次她藏在窗帘后。第二次站在镜子里。第三次，我把手机伸到床下面，她的手碰到了手机壳。</p><p>最可怕的是，我妈在门外叫我的小名。可我那时候正在和我妈通电话。</p><blockquote>别开门。门外的东西不是来接你的。<br>她越像你认识的人，越不要答应她。</blockquote><p>周某要我写“屋内无人，本人独住”。提交预览却把我写成了“唯一住户”。原来这些照片不是证明房子没鬼，是把她从这间屋子的记录里抹掉，把我填进去。</p><p>我从老报道找到了她的姓名，又回头在照片上标出她：窗帘、镜子、床底。报告选<strong>发现其他居住者</strong>，写上她的全名，把标记照片发给屋外的人留底。我同学收到之后，我才敢点<strong>终止试睡，归还房源</strong>。</p><p>门没再响。红鞋回到了鞋柜。我把钥匙放下，没有答应入住，也没有答应让谁进来。楼道灯终于亮了。</p><p>我逃出来了。但昨晚有人用我的头像给我发了消息：<br>“你走了，今晚谁来睡？”</p><p class="muted">作者此后未再更新。</p>'},
{id:'company',source:'安住不动产 · 服务说明',title:'夜间房源体验服务与报告说明',keys:['安住','试睡','公司','工作','报告'],snippet:'记录房屋客观状态，提交完整影像；特殊情况可以终止体验并说明原因。',body:'<div class="masthead" style="color:#477365;border-color:#477365">安住不动产</div><h2>夜间房源体验说明</h2><p>体验员通过现场影像记录及主观描述反馈房屋状况。照片需包含指定位置，禁止使用历史素材。</p><p>如出现无法继续体验的情况，可在报告中选择“发现其他居住者”，核实身份、保留照片并终止试睡。</p><p>所有体验报告应如实填写。“本人独住”代表体验员确认该房源没有其他居住者。</p><p class="muted">安住不动产 · 房源体验服务</p>'}
];
function browser(){if(S.view.startsWith('article:')){const a=ARTICLES.find(a=>a.id===S.view.slice(8));return appHeader(a?.source||'网页','search-back',B('bookmark',I('heart')))+`<div class="scroll article">${a?.body||'<p>页面不存在。</p>'}</div>`;}return appHeader('浏览器','home',B('history',I('clock')))+`<div class="scroll" style="background:#fff"><div class="browser-home"><h2>搜<span>一下</span></h2><form class="search-form" id="search-form"><div class="searchbox">${I('search')}<input id="search-input" aria-label="搜索关键词" placeholder="搜索网页、公司或地点" value="${esc(S.query)}"></div><button type="submit">搜索</button></form><p>${S.query?'搜索结果来自已收录网页':'有问题，搜一下。'}</p></div>${S.query?`<div class="search-results">${searchResults()}</div>`:`<div class="pad"><p class="muted">最近搜索</p>${S.history.slice(-5).reverse().map(q=>B('search-term',esc(q),'setting',{q})).join('')||'<p class="muted" style="margin-top:15px">暂无搜索记录</p>'}</div>`}</div>`;}
function searchResults(){const q=S.query.toLowerCase().trim(),found=ARTICLES.filter(a=>a.keys.some(k=>q.includes(k.toLowerCase())||k.toLowerCase().includes(q)));return found.length?found.map(a=>B('article',`<small>${a.source}</small><h3>${a.title}</h3><p>${a.snippet}</p>`,'result',{id:a.id})).join(''):'<p class="empty">没有找到相关页面。<br>可以试试公司名称、房源地址或帖子中的关键词。</p>';}
function report(){if(S.uploads.length<5)return appHeader('体验报告','stay-home')+'<p class="empty">请先提交五个指定机位的照片。</p>';return appHeader('夜间体验报告','stay-home')+`<div class="scroll pad"><div class="eyebrow">槐安里6栋604 · 体验记录</div><h2 style="font-size:24px;line-height:1.5">请如实描述<br>今晚的居住情况。</h2><form id="report-form"><label class="formfield">房屋状态<select id="report-finding"><option value="unknown" ${S.report.finding==='unknown'?'selected':''}>请选择</option><option value="alone" ${S.report.finding==='alone'?'selected':''}>房内无人，本人独住</option><option value="occupied" ${S.report.finding==='occupied'?'selected':''}>发现其他居住者</option></select></label><label class="formfield">其他居住者姓名（如有）<input id="resident-name" placeholder="请填写真实姓名" autocomplete="off" maxlength="20" value="${esc(S.report.name)}"></label><div class="card"><h3>附件</h3><p>5张现场原片${Object.keys(S.marks).length?' · '+Object.keys(S.marks).length+'处异常标记':''}</p><p>${S.flags.shared?'已由小张是好bro接收备份':'尚未分享给外部联系人'}</p></div><p class="error" id="report-error"></p><button class="primary" type="submit">预览并提交报告</button></form><p class="muted" style="margin-top:18px">签名前请核对居住声明。记录提交后将归入房源档案。</p></div>`;}
function settings(){return appHeader('设置','home')+`<div class="scroll"><div class="pad"><h2 style="font-size:29px">这部手机</h2><p class="muted">林砚的手机 · 本机存档</p></div>${B('toggle-setting',`<span>声音<small>环境低鸣、快门、通知与惊吓音效</small></span><span class="toggle ${S.settings.sound?'on':''}"><i></i></span>`,'setting',{id:'sound'})}${B('toggle-setting',`<span>强烈惊吓<small>关闭后减弱突脸动画与冲击音效</small></span><span class="toggle ${S.settings.intense?'on':''}"><i></i></span>`,'setting',{id:'intense'})}${B('hint','需要一点提示'+I('next'),'setting')}${B('restore','从最近的拍摄检查点继续'+I('next'),'setting')}${B('restart','重新开始这一夜'+I('next'),'setting')}${B('about','关于《请确认入住》'+I('next'),'setting')}<div class="pad"><p class="muted">进度自动保存在此浏览器。<br>底部横条返回桌面 · Esc 返回 · F 全屏</p></div></div>`;}
function phoneView(){return appHeader('电话','home')+`<div class="scroll"><div class="pad"><h2 style="font-size:29px">通讯录</h2><p class="muted">保存的号码</p></div>${['mom','dad','friend','landlord',...(S.hired?['hr']:[])].map(id=>B('call',`${AV(id)}<div class="rowtext"><b>${PEOPLE[id].name}</b><p>${PEOPLE[id].number}</p></div>`,'chatrow',{id})).join('')}${B('call',`<span class="avatar brand">110</span><div class="rowtext"><b>报警求助</b><p>游戏内接警电话</p></div>`,'chatrow',{id:'police'})}<div class="pad"><h3 style="font-size:16px">最近通话</h3>${S.calls.slice(-4).reverse().map(c=>`<p class="muted">${c.at}　${esc(c.name)} · ${esc(c.status)}</p>`).join('')||'<p class="muted">暂无通话</p>'}</div></div>`;}
function files(){return appHeader('文件','home')+`<div class="scroll pad"><h2 style="font-size:28px;margin-bottom:23px">最近项目</h2>${B('resume-file',I('files')+'<span>林砚_个人简历.pdf</span>'+I('next'),'setting')}${S.hired?B('contract',I('files')+'<span>安住_试睡预约单.pdf</span>'+I('next'),'setting'):''}${S.checked?B('open',I('photos')+`<span>604现场原片（${S.photos.length}）</span>`+I('next'),'setting',{app:'photos'}):''}</div>`;}
function ending(){const good=S.ending==='escape';return `<div class="end-view ${good?'':'bad'}"><div class="eyebrow">${good?'06:03 / OUTSIDE':'06:00 / STILL INSIDE'}</div><h2>${good?'今夜，不入住。':'恭喜，入住成功。'}</h2><div class="end-line">${good?'发送成功的提示音响起。门后的敲击停了。<br><br>你把钥匙放回鞋柜。红色拖鞋安静地并在一旁，鞋尖不再朝着你。<br><br>楼道里，感应灯一盏接着一盏亮起。':'屏幕显示“结算成功”。<br><br>你抬起头，天却没有亮。门把手不见了。照片里那个女人已经站到你身后。<br><br>这一次，相机没有开。'}</div><div class="receipt">${good?'妈妈：小砚，工作不合适就回来。<br>妈妈：馄饨给你留着呢。<br><br>你：妈，我今天不上班了。':'安住不动产 · 房源档案已更新<br>原居住人：已注销<br>当前唯一住户：林砚<br>居住期限：长期<br><br>biss直聘：该岗位正在招聘下一位体验员。'}</div><div class="eyebrow">结局 · ${good?'拒绝入住':'唯一住户'}</div><div class="buttons">${primary('ending-photos','查看这一夜的照片')}${B('restore','回到报告提交前','secondary')}${B('restart','重新开始','secondary')}</div></div>`;}
const VIEWS={home,wechat,biss,stay,camera,photos,photo,browser,map:mapView,settings,phone:phoneView,files,ending,notes:()=>appHeader('备忘录','home')+`<div class="notebook"><h2>随手记</h2><textarea id="notes-input" aria-label="备忘录">${esc(S.notes)}</textarea><small class="muted">自动保存到本机</small></div>`,clock:()=>appHeader('时钟','home')+`<div class="clockface"><strong>${time()}</strong><p>临川 · 9月${S.time>=1440?'14':'13'}日</p><p>日出　05:42</p><p style="margin-top:55px">${S.checked?'夜还很长。':'明天会是新的一天。'}</p></div>`};
function drawPhotoMark(){const img=$('#evidence-image'),stage=$('#photo-stage');if(!img||!stage)return;stage.querySelector('.mark-ring')?.remove();const mark=S.marks[S.view];if(!mark||R.compare)return;const ir=img.getBoundingClientRect(),sr=stage.getBoundingClientRect();if(!ir.width||!ir.height)return;const ring=document.createElement('span');ring.className='mark-ring';ring.setAttribute('aria-label','已标记的异常位置');ring.style.left=ir.left-sr.left+stage.scrollLeft+ir.width*mark.x+'px';ring.style.top=ir.top-sr.top+stage.scrollTop+ir.height*mark.y+'px';stage.appendChild(ring);}
function render(){if(S.ending&&S.app!=='photos'&&S.app!=='photo'&&S.app!=='settings'&&!(S.ending==='redemption'&&S.app==='wechat'&&['','chats','contacts','hr','profile:hr','album:hr'].includes(S.view)))S.app='ending';$('#phone').dataset.app=S.app;renderStatus();$('#screen').innerHTML=(VIEWS[S.app]||home)();$('#system').innerHTML=B('home','<i></i>','',{label:'返回桌面'});for(const el of document.querySelectorAll('[data-label]'))el.setAttribute('aria-label',el.dataset.label);if(S.app==='camera')requestAnimationFrame(drawCamera);if(S.app==='photo'){const img=$('#evidence-image');if(img){img.addEventListener('load',drawPhotoMark,{once:true});requestAnimationFrame(drawPhotoMark);}}if(S.app==='wechat'&&PEOPLE[S.view]){const sc=$('#chatbody');if(sc)sc.scrollTop=sc.scrollHeight;}syncAmbience();}
function back(){if($('#modal').innerHTML){close();return;}if(R.scareLeft){R.scareLeft=0;$('#scare').className='';return;}if(S.app==='photo')return open('photos');if(S.app==='wechat'){if(PEOPLE[S.view])return open('wechat');if(S.view==='moments')return open('wechat','discover');return open('wechat');}if(S.app==='biss'&&S.view)return open('biss');if(S.app==='stay'&&S.view)return open('stay');if(S.app==='browser'&&S.view)return open('browser');if(S.app==='camera')return open('stay');return open('home');}
function apply(){if(S.applied)return open('wechat','hr');S.applied=true;nowAdd(2);addMsg('hr','你好，我是安住不动产的周先生。看过你的简历了，摄影基础正好适合。');addMsg('hr','今晚的房源在槐安里。23:50到，住到天亮，五个位置拍照，1200元日结。');addMsg('hr','房子以前确实出过事，不过你只要拍照、填报告。不直播、不收押金。你能接受吗？');open('wechat','hr');}
function acceptOffer(){if(S.hired)return open('stay');S.hired=true;nowAdd(3);addMsg('hr','可以，我想试试。',true);addMsg('hr','订单发到「安住试睡」了。槐安里6栋604。到楼下给我消息，我告诉你钥匙在哪。');addMsg('mom','妈，我找到一份试岗，今晚去。',true);addMsg('mom','什么工作？地址发我。晚上一个人注意安全。');open('stay');checkpoint();notify('威信 · 妈妈','什么工作？地址发我。','wechat','mom');}
function checkin(){if(!S.arrived||S.checked)return;S.checked=true;S.time=23*60+58;addMsg('hr','我进来了。',true);addMsg('hr','先拍玄关。左边鞋柜，正前方入户门。每拍完一张，从照片页面发给我。');addMsg('hr','别动红鞋，原屋主的东西不要挪。');open('camera','hall');checkpoint();tone('knock');}
function capture(id){if(R.busy||!unlocked(id)||S.ending)return;R.busy=true;const r=room(id);const first=!hasPhoto(id);if(first){nowAdd(id==='hall'?1:11);S.photos.push({room:id,at:time()});if(id==='living'){addMsg('hr','客厅拍好了没有？窗帘后面不用看，拍全就行。');}if(id==='bath'&&!S.messages.unknown){addMsg('unknown','你现在是不是在604？');addMsg('unknown','相机里的不是反光。别照床底。');}if(id==='bed'){addMsg('mom','小砚，妈来接你了。');addMsg('mom','在门外呢，把门开一下。');addMsg('unknown','我以前的帖子还在。搜“住过604的人”。名字在旧报道里，不要信负责人。');}if(id==='door'){addMsg('mom','怎么还不开门？我看见你拿着手机了。');}save();checkpoint();}tone('shutter');if(S.flash&&S.settings.intense){$('#flash').className='on';setTimeout(()=>$('#flash').className='',270);}setTimeout(()=>{R.busy=false;open('photo',id);if(first&&id==='bed')setTimeout(()=>{if(S.app==='photo'&&S.view==='bed')scare('她刚才碰到了你的手机。');},650);if(first&&id==='door')tone('knock');},220);}
function upload(id){if(!hasPhoto(id))return;if(S.uploads.includes(id))return open('stay');if(id!==ROOMS[S.uploads.length]?.id){sheet('提交顺序','<p>请先提交工作清单中的上一张照片。</p>');return;}S.uploads.push(id);addMsg('hr','',true,{image:id});addMsg('hr',room(id).response);if(id==='living')addMsg('friend','妈给我打电话了，说你去做夜班。你地址发我一下？');if(id==='door'){checkpoint();}save();open('wechat','hr');notify('安住试睡',id==='door'?'影像记录已完成，请填写体验报告。':'新拍摄要求已更新。','stay');}
function markPoint(event){if(!R.marking||R.compare)return;const r=room(S.view);if(!r.area)return;const img=event.currentTarget,rect=img.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width,y=(event.clientY-rect.top)/rect.height;const [x1,y1,x2,y2]=r.area;if(x>=x1&&x<=x2&&y>=y1&&y<=y2){S.marks[r.id]={x,y};R.marking=false;save();render();notify('照片 · 异常已标记',r.clue,'photo',r.id);if(r.id==='bath'&&!S.flags.mirrorScare){S.flags.mirrorScare=true;save();setTimeout(()=>{if(S.app==='photo'&&S.view==='bath')scare('她在玻璃的另一边，敲了一下。');},350);}}else notify('照片','这里暂时没有明显异常，试试放大后检查暗处。','photo',r.id);}
function shareFriend(){if(S.photos.length<2){addMsg('friend','等你拍了照片发我看看。');return render();}S.sharedPhotos??=[];const fresh=S.photos.filter(p=>p.room!=='hall'&&!S.sharedPhotos.includes(p.room));fresh.forEach(p=>{addMsg('friend','',true,{image:p.room});S.sharedPhotos.push(p.room);});if(fresh.length){addMsg('friend','照片收到了，我都存下来了。你把地址留给我，别关机。');addMsg('friend','你查查“槐安里604”，以前好像出过事。之后拍到的也发我，我会一直看着消息。');}else addMsg('friend','发来的照片我已经存好了。别删你那边的原片。');S.flags.shared=['living','bath','bed'].every(id=>S.sharedPhotos.includes(id));save();open('wechat','friend');}
function call(id){let name=PEOPLE[id]?.name||'报警求助',line='',status='已接通';if(id==='mom'){if(S.photos.length>=4){line='小砚？我在家里，跟你爸一起。什么门外？妈妈根本没去临川。\n\n你听我说，别给那个人开门。把地址发给小张是好bro，妈妈现在就联系她。';S.flags.calledMom=true;}else line='怎么啦小砚？工作的事慢慢来。你爸嘴上说得硬，刚才还问我你钱够不够花。';}else if(id==='dad')line='爸在家呢。你妈就在旁边。\n\n工作不对劲就回来，别为了这点钱硬撑。';else if(id==='friend')line=S.checked?'我收到你发的地址了。你先把照片备份给我。我在外面，能帮你留证。别点负责人让你签的东西。':'还在改简历吗？有工作了先发给我看看，别一个人扛着。';else if(id==='hr')line=S.photos.length>=3?'拍照。填报告。\n\n你不是一直想找个地方，留下来吗？':'你好，安住。具体事项威信说，通话不方便。';else if(id==='unknown'){status='未接通';line='对方账号暂时无法接通语音。';}else if(id==='police'){line=S.checked?'这里是接警台。地址是槐安里6栋604，对吗？请保持电话畅通，我们正在联系辖区值班人员。\n\n不要打开来历不明的敲门声对应的门，尽量与可信联系人保持联系。':'这里是接警台。请说明具体地点与情况。';S.flags.police=true;}else line='小林，怎么这么晚打来？有事你威信留个言，我明早看。';S.calls.push({id,name,status,at:time()});save();sheet(name,`<div class="calling">${PEOPLE[id]?.image?`<img class="call-avatar" src="assets/${PEOPLE[id].image}" alt="${name}">`:''}<h3>${name}</h3><small>${status} · ${PEOPLE[id]?.number||'语音通话'}</small><p class="transcript">${esc(line).replace(/\n/g,'<br>')}</p>${B('close',I('phone')+' 挂断','danger')}</div>`);tone('notify');}
function reply(id,text){text=text.trim();if(!text)return;addMsg(id,text,true);S.drafts[id]='';if(id==='mom'){if(!S.flags.repliedMom){S.flags.repliedMom=true;addMsg('mom','嗯。别嫌我唠叨，先看看招聘，有合适的就去聊聊。');}else if(S.photos.length>=4&&!S.flags.calledMom)addMsg('mom','先把门打开，妈就在外面。');else addMsg('mom','好，注意安全。到了跟妈说一声。');}else if(id==='hr'){if(!S.hired)addMsg('hr','岗位详情都在邀请里。确定的话，点下方接受试岗。');else if(S.photos.length>=2)addMsg('hr','先按清单拍完。不需要判断照片里是什么，我看得见。');else addMsg('hr','看工作清单就好，每张拍完记得发我。');}else if(id==='friend')addMsg('friend',S.photos.length>=2?'把照片发我，我给你存一份。你可以搜一下房源地址。':'我在呢。可以先去biss看看，聊过了再决定。');else if(id==='unknown')addMsg('unknown','去搜我以前发的帖子：住过604的人。不要填“本人独住”。');else addMsg(id,id==='dad'?'嗯，爸看到了。有什么事就打电话。':'收到。');save();render();}
function doSearch(q){S.query=q.trim().slice(0,100);if(S.query&&!S.history.includes(S.query))S.history.push(S.query);open('browser');}
function readArticle(id){if(!ARTICLES.some(a=>a.id===id))return;if(!S.read.includes(id))S.read.push(id);open('browser','article:'+id);}
function submitReport(){S.report.finding=$('#report-finding').value;S.report.name=$('#resident-name').value.trim();save();const err=$('#report-error');if(S.uploads.length<5)return;if(S.report.finding==='unknown'){err.textContent='请选择房屋居住情况。';return;}if(S.report.finding==='alone'){sheet('入住声明 · 签名前核对','<p>本人确认：本房源内没有其他居住者，同意登记为本房源<strong>唯一住户</strong>。</p><p class="muted">体验补贴：1800元<br>登记人：林砚<br>房源：槐安里6栋604</p>'+primary('sign-alone','确认入住，领取补贴')+B('close','返回修改','secondary'));return;}if(S.report.name.replace(/\s/g,'')!=='沈秋宁'){err.textContent='其他居住者身份尚未核实。可以从房源的历史报道核对姓名。';return;}const missing=['living','bath','bed'].filter(id=>!S.marks[id]);if(missing.length){err.textContent='请在'+missing.map(id=>room(id).name).join('、')+'原片上标出她的位置，作为异常说明附件。';return;}if(!S.flags.shared){err.textContent='照片还只在你和雇主手里。先发给屋外可信的人保留一份。';return;}checkpoint();sheet('终止试睡 · 房源归还',`<p>其他居住者：<strong>沈秋宁</strong><br>异常影像：窗帘、镜子、床底<br>外部联系人：小张是好bro，已接收照片</p><p>本人仅为临时体验员，不确认独住，不接受居住人变更。现终止试睡，归还房源。</p>${primary('escape','终止试睡，归还钥匙')}${B('close','再检查一下','secondary')}`);}
function finish(type){if(S.ending)return;checkpoint();S.ending=type;S.route=null;if(type==='escape'){S.time=Math.max(S.time,24*60+6*60+3);addMsg('friend','我到小区门口了。看见你了，快出来。');addMsg('mom','工作不合适就回来。馄饨给你留着呢。');}else{S.time=Math.max(S.time,24*60+6*60);addMsg('hr','恭喜，入住成功。以后这里就是你的家。');}save();open('ending');if(type==='trapped')scare('现在，轮到你住在这里了。');}
function restore(){let cp;try{cp=JSON.parse(localStorage.getItem(CHECKPOINT));}catch{}if(!cp){sheet('还没有检查点','<p>接受试岗或拍摄照片后会自动保存检查点。</p>');return;}const settings=S.settings;S={...initial(),...cp,settings};S.ending=null;R.scareLeft=0;$('#scare').className='';open('stay');save();}
function hint(){let text;if(!S.applied)text='妈妈在威信里催你找工作。打开biss直聘，看看那份按晚结算的职位。';else if(!S.hired)text='周先生已经发来试岗邀请，在威信里回复并接受。';else if(!S.checked)text='在安住试睡里查看订单，按地图前往槐安里，再取钥匙进入604。';else if(S.uploads.length<5){const id=nextRoom();text=hasPhoto(id)?'刚拍好的照片需要从照片底栏“发给雇主”，才能收到下一项要求。':'当前任务是'+room(id).subtitle+'。取景与照片可以对照；可疑位置能够放大标记。';}else if(!S.read.includes('forum'))text='上一位试睡员提到了自己的旧帖。在浏览器搜索“住过604的人”。房源旧报道能核对原屋主的姓名。';else if(!S.flags.shared)text='把异常原片发给威信里的室友小张是好bro，让屋外的人留一份。';else text='报告可以如实填写：找到原住户全名，标出客厅窗帘、浴室镜子和床底的人，再终止试睡。';sheet('一点提示','<p>'+text+'</p>');}
const ACTIONS={open:d=>open(d.app,d.view||''),home:()=>open('home'),back,close,notice:()=>{if(R.notice)open(R.notice.app,R.notice.view);},tab:d=>{if(['jobs','biss-messages','resume'].includes(d.id))open('biss',d.id==='jobs'?'':d.id==='biss-messages'?'messages':'resume');else open('wechat',d.id);},chat:d=>open('wechat',d.id),profile:d=>open('wechat','profile:'+d.id),'wx-list':()=>open('wechat'),'wx-discover':()=>open('wechat','discover'),moments:()=>open('wechat','moments'),'biss-home':()=>open('biss'),'stay-home':()=>open('stay'),'search-back':()=>open('browser'),'photo-back':()=>open('photos'),job:d=>open('biss','job:'+d.id),apply,'accept-offer':acceptOffer,'ask-risk':()=>{addMsg('hr','原屋主几年前在里面去世了，所以要做体验。你只管拍照，不用调查过去的事。');render();},reply:d=>reply(d.id,d.text),call:d=>call(d.id),'share-friend':shareFriend,'hr-question':()=>reply('hr','照片里的人是什么？我想停止试睡。'),'ask-unknown':()=>reply('unknown','你是上一位试睡员？'),navigate:()=>{if(S.hired&&!S.arrived&&!S.route){S.route={elapsed:0,paused:false};save();render();}},'route-pause':()=>{if(S.route){S.route.paused=!S.route.paused;save();render();}},checkin,task:d=>{if(!unlocked(d.id))return notify('安住试睡','先完成前一项拍摄并提交照片。','stay');open(hasPhoto(d.id)?'photo':'camera',d.id);},room:d=>{if(unlocked(d.id))open('camera',d.id);},shutter:d=>capture(d.id),'latest-photo':()=>open(S.photos.length?'photo':'photos',S.photos.at(-1)?.room||''),'view-photo':d=>{if(hasPhoto(d.id))open('photo',d.id);},zoom:()=>{R.zoom=!R.zoom;render();},compare:()=>{R.compare=!R.compare;R.marking=false;render();},mark:d=>{if(d.id==='hall')return notify('照片','玄关初始照片没有发现人影。保留它，之后可以对照。','photo','hall');R.marking=!R.marking;R.compare=false;render();},upload:d=>upload(d.id),flash:()=>{S.flash=!S.flash;save();render();},'camera-help':()=>sheet('相机','<p>选择要检查的房间，按快门拍照。拍摄原片保存在相册中，可以放大、对照取景、标记异常并发给雇主。</p><p>这里的相机拍摄游戏中的房屋。</p>'),'photo-details':d=>sheet('照片信息',`<p>${room(d.id).name} · ${S.photos.find(p=>p.room===d.id)?.at||''}<br>来源：本机相机<br>处理：未修图<br>保留快门前取景作为对照。</p>`),'leave-early':()=>{if(S.uploads.length===5)return open('stay','report');sheet('终止试睡','<p>你拧动门把手，锁舌没有响。钥匙转了整整一圈，又回到原位。</p><p>周先生发来消息：“缺少现场照片，无法提交异常报告。拍完再说。”</p>'+primary('chat','联系负责人',{id:'hr'})+B('open','查看照片与线索','secondary',{app:'photos'}));},report:()=>open('stay','report'),'sign-alone':()=>finish('trapped'),escape:()=>finish('escape'),'ending-photos':()=>open('photos'),article:d=>readArticle(d.id),'search-term':d=>doSearch(d.q),history:()=>sheet('搜索历史',S.history.length?S.history.slice().reverse().map(q=>B('search-term',esc(q),'setting',{q})).join(''):'<p>还没有搜索记录。</p>'),bookmark:()=>{S.flags.bookmark=S.view;save();notify('浏览器','页面已保存在本机书签。','browser',S.view);},'toggle-setting':d=>{S.settings[d.id]=!S.settings[d.id];save();render();},hint,restore:()=>sheet('恢复检查点','<p>回到最近一次拍摄或提交报告前的进度。声音设置会保留。</p>'+primary('restore-now','恢复检查点')), 'restore-now':restore,restart:()=>sheet('重新开始','<p>清除这一夜的聊天、照片与进度，回到最初的手机桌面？</p>'+B('reset-now','重新开始','danger')+B('close','继续这一夜','secondary')),'reset-now':()=>{const settings=S.settings;S=initial();S.settings=settings;try{localStorage.removeItem(CHECKPOINT);}catch{}R.scareLeft=0;$('#scare').className='';open('home');save();notify('威信 · 妈妈','小砚，今天投了几家？','wechat','mom');},about:()=>sheet('请确认入住','<p>凶宅试睡 · 本地 Demo<br>一份深夜工作，一部不该拍照的手机。</p><p>场景、鬼影及突脸图片由内置 image_gen 生成。招聘、聊天、电话、地图与相机均为剧情模拟，故事与人物为虚构。</p><p class="muted">浏览器自动存档 · 两种结局<br>设置中可关闭声音与强烈惊吓。</p>'),weather:()=>sheet('临川天气','<p style="font-size:46px">18°</p><p>小雨 · 体感16°<br>东北风 2级 · 湿度91%<br>日出 05:42 · 日落 18:09</p>'),calendar:()=>sheet('9月13日 · 星期日','<p>今天没有日程。</p><p>周五：交房租<br>下周一：继续投递简历</p>'),like:()=>{S.flags.liked=!S.flags.liked;save();render();},'save-job':()=>{S.flags.savedJob=true;save();notify('biss直聘','已收藏该职位。','biss',S.view);},'normal-apply':d=>sheet('沟通已发送',`<p>${d.id==='normal2'?'招聘人：抱歉，目前只考虑有相关经验的候选人。':'你发送了简历。招聘人暂未回复。'}</p>`),'job-search':()=>sheet('搜索职位',`<p>与“应届生、夜间、日结”匹配的职位：</p>${primary('job','凶宅试睡员 · 1200元/晚',{id:'haunted'})}`),'resume-file':()=>open('biss','resume'),contract:()=>sheet('试睡预约单','<p>体验员：林砚<br>房源：槐安里6栋604<br>报到：9月13日23:50<br>报酬：1200元/晚</p><p>预约仅安排临时体验，不确认房屋居住状态。最终状态以体验员签署的报告为准。</p>'),'contacts-help':()=>sheet('通讯录','<p>点击联系人查看资料、发消息或拨打语音电话。</p>'),'wx-search':()=>sheet('搜一搜',`<label class="formfield">搜索联系人<input id="contact-search" placeholder="输入名字"></label><div id="contact-results">${Object.keys(S.messages).map(id=>B('chat',PEOPLE[id].name,'setting',{id})).join('')}</div>`),attach:d=>sheet('发送照片',S.photos.length?S.photos.map(p=>B(d.id==='friend'?'share-friend':'upload',room(p.room).name+' · '+p.at,'setting',{id:p.room})).join(''):'<p>还没有拍摄照片。</p>')};
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;if(R.scareLeft>0&&btn.dataset.action!=='home')return;tone('tap');syncAmbience();ACTIONS[btn.dataset.action]?.(btn.dataset,e);});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chat-form')reply(e.target.dataset.id,$('#chat-input').value);if(e.target.id==='search-form')doSearch($('#search-input').value);if(e.target.id==='report-form')submitReport();});
document.addEventListener('input',e=>{if(e.target.id==='notes-input'){S.notes=e.target.value;save();}if(e.target.id==='chat-input'){S.drafts[S.view]=e.target.value;save();}if(e.target.id==='resident-name'){S.report.name=e.target.value;if(document.querySelector('#report-error'))document.querySelector('#report-error').textContent='';save();}if(e.target.id==='contact-search'){const q=e.target.value.trim();$('#contact-results').innerHTML=Object.keys(S.messages).filter(id=>PEOPLE[id].name.includes(q)).map(id=>B('chat',PEOPLE[id].name,'setting',{id})).join('')||'<p class="muted">没有找到联系人。</p>';}});
document.addEventListener('change',e=>{if(e.target.id==='report-finding'){S.report.finding=e.target.value;save();}});
document.addEventListener('pointerup',e=>{if(e.target.id==='evidence-image')markPoint({...e,currentTarget:e.target,clientX:e.clientX,clientY:e.clientY});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();back();}if(e.key.toLowerCase()==='f'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){if(document.fullscreenElement)document.exitFullscreen?.();else $('#phone').requestFullscreen?.().catch(()=>{});}});
window.addEventListener('resize',()=>{if(S.app==='camera')drawCamera();if(S.app==='photo')drawPhotoMark();});document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();save();syncAmbience();});
function advance(ms){if(document.hidden)return;S.elapsed+=ms;if(!S.ending)S.time+=ms/60000;if(R.noticeLeft>0){R.noticeLeft-=ms;if(R.noticeLeft<=0)renderNotice();}if(R.scareLeft>0){R.scareLeft-=ms;if(R.scareLeft<=0){$('#scare').className='';$('#scare').setAttribute('aria-hidden','true');}}if(S.route&&!S.route.paused){S.route.elapsed+=ms;if(S.route.elapsed>=6500){S.route=null;S.arrived=true;S.time=23*60+50;addMsg('hr','到6栋楼下了吗？上六楼，604。门口钥匙盒0614，进去先拍玄关。');save();if(S.app==='map')render();notify('威信 · 周先生','钥匙盒密码0614，进去先拍玄关。','wechat','hr');}else if(S.app==='map'){const fill=$('#route-fill'),text=$('#route-text');if(fill)fill.style.width=S.route.elapsed/6500*100+'%';if(text)text.textContent='正在前往房源 · '+Math.floor(S.route.elapsed/6500*100)+'%';}}}
window.advanceTime=ms=>{advance(Math.max(0,Number(ms)||0));renderStatus();save();};
window.render_game_to_text=()=>JSON.stringify({title:'请确认入住',app:S.app,view:S.view,time:time(),phase:S.ending?'ending':S.checked?'trial':S.arrived?'arrived':S.hired?'hired':S.applied?'interview':'job-search',currentTask:ROOMS[S.uploads.length]?.subtitle||'填写体验报告',location:S.checked?'槐安里6栋604':S.arrived?'槐安里6栋楼下':'出租屋',photos:S.photos.map(p=>({room:p.room,name:room(p.room).name,uploaded:S.uploads.includes(p.room),marked:!!S.marks[p.room]})),photoViewer:{zoom:R.zoom,compare:R.compare,marking:R.marking},readArticles:S.read,backup:S.flags.shared||false,motherVerified:S.flags.calledMom||false,route:S.route,scareVisible:R.scareLeft>0,ending:S.ending,coordinates:'照片左上角为(0,0)，x向右，y向下；标记坐标按图片宽高归一化',visibleActions:[...document.querySelectorAll('#screen button,#modal button')].map(b=>({action:b.dataset.action,text:b.textContent.trim(),id:b.dataset.id||b.dataset.app})).filter(x=>x.action)});
function frame(now){const dt=Math.min(now-lastFrame,100);lastFrame=now;if(!document.hidden){advance(dt);if(now-lastSaved>1500){renderStatus();save();lastSaved=now;}}requestAnimationFrame(frame);}
